def transform(grid):
    anchors=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==5]
    # Choose the 5 with nearby nonzero pattern as source; copy its pattern to the isolated 5.
    def density(p):
        r,c=p
        return sum(grid[rr][cc]!=0 for rr in range(max(0,r-3),min(len(grid),r+4)) for cc in range(max(0,c-3),min(len(grid[0]),c+4)) if (rr,cc)!=p)
    src=max(anchors,key=density); dst=next(p for p in anchors if p!=src)
    dr,dc=dst[0]-src[0],dst[1]-src[1]
